import { Tabs } from 'expo-router';
import React, { useEffect, useRef } from 'react';
import { Platform, View, Text, Animated, StyleSheet, Dimensions, TouchableOpacity } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { useAppTheme } from '@/context/ThemeContext';
import { BottomTabBarProps } from '@react-navigation/bottom-tabs';

const { width: windowWidth } = Dimensions.get('window');

function getIconName(routeName: string) {
  switch (routeName) {
    case 'agent': return 'wallet';
    case 'transfers': return 'swap-horizontal';
    case 'index': return 'home';
    case 'payments': return 'card';
    case 'account': return 'person';
    default: return 'home';
  }
}

const TabIconWrapper = ({ name, isFocused, activeColor, inactiveColor }: any) => {
  const translateY = useRef(new Animated.Value(isFocused ? -14 : 0)).current;

  useEffect(() => {
    Animated.spring(translateY, {
      toValue: isFocused ? -14 : 0,
      useNativeDriver: true,
      friction: 7,
      tension: 45,
    }).start();
  }, [isFocused]);

  const activeIconName = name;
  const inactiveIconName = name === 'swap-horizontal' ? 'swap-horizontal' : `${name}-outline`;

  return (
    <View style={{ width: 44, height: 44, alignItems: 'center', justifyContent: 'center', zIndex: 10 }}>
      <Animated.View style={{ transform: [{ translateY }] }}>
        <Ionicons 
          name={isFocused ? activeIconName : inactiveIconName} 
          size={isFocused ? 26 : 24} 
          color={isFocused ? activeColor : inactiveColor} 
        />
      </Animated.View>
    </View>
  );
};

function CustomTabBar({ state, descriptors, navigation, colors, isDark }: BottomTabBarProps & { colors: any; isDark: boolean }) {
  const tabWidth = windowWidth / 5;
  const circleWidth = 58;
  const centerOffset = (tabWidth - circleWidth) / 2;

  const activeIndex = state.index;
  const slideAnim = useRef(new Animated.Value(activeIndex * tabWidth + centerOffset)).current;

  useEffect(() => {
    Animated.spring(slideAnim, {
      toValue: activeIndex * tabWidth + centerOffset,
      useNativeDriver: true,
      friction: 7,
      tension: 45,
    }).start();
  }, [activeIndex]);

  return (
    <View style={[styles.tabBarContainer, { backgroundColor: isDark ? '#111111' : '#FFFFFF' }]}>
      {/* Sliding Gold Circle Backdrop */}
      <Animated.View style={[styles.slidingCircle, {
        backgroundColor: colors.primary || '#D4AF37',
        transform: [{ translateX: slideAnim }],
        shadowColor: colors.primary || '#D4AF37',
      }]} />

      {state.routes.map((route, index) => {
        const { options } = descriptors[route.key];
        const label = options.title !== undefined ? options.title : route.name;
        const isFocused = state.index === index;

        const onPress = () => {
          const event = navigation.emit({
            type: 'tabPress',
            target: route.key,
            canPreventDefault: true,
          });

          if (!isFocused && !event.defaultPrevented) {
            navigation.navigate(route.name);
          }
        };

        return (
          <TouchableOpacity
            key={route.key}
            onPress={onPress}
            activeOpacity={0.9}
            style={[styles.tabItem, { width: tabWidth }]}
          >
            <TabIconWrapper 
              name={getIconName(route.name)} 
              isFocused={isFocused} 
              activeColor="#000000" 
              inactiveColor={isDark ? '#718096' : '#A0AEC0'} 
            />
            <Text style={[
              styles.tabLabel, 
              { 
                color: isFocused ? (colors.primary || '#D4AF37') : (isDark ? '#718096' : '#A0AEC0'),
                fontFamily: colors.fontFamily || 'System'
              }
            ]}>
              {label}
            </Text>
          </TouchableOpacity>
        );
      })}
    </View>
  );
}

export default function TabLayout() {
  const { colors, isDark } = useAppTheme();

  return (
    <Tabs
      tabBar={(props) => <CustomTabBar {...props} colors={colors} isDark={isDark} />}
      screenOptions={{
        headerShown: false,
      }}>

      <Tabs.Screen
        name="agent"
        options={{ title: 'Comptes' }}
      />

      <Tabs.Screen
        name="transfers"
        options={{ title: 'Transferts' }}
      />

      <Tabs.Screen
        name="index"
        options={{ title: 'Accueil' }}
      />

      <Tabs.Screen
        name="payments"
        options={{ title: 'Paiements' }}
      />

      <Tabs.Screen
        name="account"
        options={{ title: 'Compte' }}
      />

    </Tabs>
  );
}

const styles = StyleSheet.create({
  tabBarContainer: {
    flexDirection: 'row',
    position: 'absolute',
    bottom: 0,
    left: 0,
    right: 0,
    elevation: 25,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: -8 },
    shadowOpacity: 0.08,
    shadowRadius: 15,
    height: Platform.OS === 'ios' ? 95 : 75,
    paddingBottom: Platform.OS === 'ios' ? 30 : 10,
    paddingTop: 10,
    borderTopLeftRadius: 30,
    borderTopRightRadius: 30,
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  slidingCircle: {
    position: 'absolute',
    top: 6,
    width: 58,
    height: 58,
    borderRadius: 29,
    marginTop: -16, // Float slightly above the bar
    shadowOffset: { width: 0, height: 6 },
    shadowOpacity: 0.4,
    shadowRadius: 8,
    elevation: 10,
    zIndex: 5,
  },
  tabItem: {
    alignItems: 'center',
    justifyContent: 'center',
    height: '100%',
    zIndex: 10,
  },
  tabLabel: {
    fontSize: 10,
    fontWeight: '700',
    marginTop: -2,
  },
});

import React, { useState, useEffect } from 'react';
import { View, Text, StyleSheet, Platform, SafeAreaView, ScrollView, TouchableOpacity, Switch } from 'react-native';
import { Feather, Ionicons } from '@expo/vector-icons';
import { useAppTheme } from '@/context/ThemeContext';
import { useAuth } from '@/context/AuthContext';
import { fetchAPI } from '@/config/api';
import { router } from 'expo-router';
import Animated, { FadeInDown, FadeInUp } from 'react-native-reanimated';

export default function AccountScreen() {
  const { colors: theme, isDark, toggleTheme } = useAppTheme();
  const { username, logout } = useAuth();
  const [kycLevel, setKycLevel] = useState(1);
  const [loading, setLoading] = useState(true);

  const KYC_TIERS: Record<number, { label: string; limit: string; color: string }> = {
    1: { label: 'Tier 1 - Standard', limit: '5,000 FCFA / jour', color: '#718096' },
    2: { label: 'Tier 2 - Argent', limit: '200,000 FCFA / jour', color: '#A0AEC0' },
    3: { label: 'Tier 3 - Or Premium', limit: '5,000,000 FCFA / jour', color: '#D4AF37' }
  };

  const currentTier = KYC_TIERS[kycLevel] || KYC_TIERS[1];

  const fetchKycStatus = async () => {
    if (!username) return;
    try {
      const res = await fetchAPI(`/auth/kyc/status`);
      setKycLevel(res.kyc_tier !== undefined ? res.kyc_tier : 1);
    } catch (err) {
      console.error("Error fetching KYC level in Account screen", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchKycStatus();
  }, [username]);

  const handleLogout = async () => {
    await logout();
    router.replace('/auth');
  };

  const initial = username ? username.charAt(0).toUpperCase() : 'U';

  return (
    <SafeAreaView style={[styles.container, { backgroundColor: theme.background }]}>
      {/* Header */}
      <Animated.View entering={FadeInDown.duration(500)} style={[styles.header, { borderBottomColor: theme.border }]}>
        <Text style={[styles.headerTitle, { color: theme.textPrimary, fontFamily: theme.fontFamily }]}>Mon Compte</Text>
        <TouchableOpacity style={[styles.iconBtn, { backgroundColor: theme.surface }]} onPress={() => router.push('/notifications')}>
          <Feather name="bell" size={20} color={theme.textPrimary} />
        </TouchableOpacity>
      </Animated.View>

      <ScrollView contentContainerStyle={styles.scrollContent} showsVerticalScrollIndicator={false}>
        {/* Profile Card */}
        <Animated.View entering={FadeInDown.duration(500).delay(100)} style={styles.profileSection}>
          <View style={[styles.avatarContainer, { borderColor: theme.primary }]}>
            <Text style={[styles.avatarText, { color: theme.primary }]}>{initial}</Text>
            <View style={[styles.verifiedBadge, { backgroundColor: theme.primary }]}>
              <Ionicons name="checkmark-sharp" size={12} color="#000" />
            </View>
          </View>

          <Text style={[styles.usernameText, { color: theme.textPrimary, fontFamily: theme.fontFamily }]}>
            {username}
          </Text>
          <Text style={[styles.phoneText, { color: theme.textSecondary, fontFamily: theme.fontFamily }]}>
            Membre XAALISI
          </Text>
        </Animated.View>

        {/* KYC Badge Card */}
        <Animated.View entering={FadeInUp.duration(500).delay(200)} style={[styles.kycCard, { backgroundColor: theme.surface, borderColor: theme.border }]}>
          <View style={styles.kycHeader}>
            <View style={{ flexDirection: 'row', alignItems: 'center' }}>
              <Ionicons name="shield-checkmark" size={20} color={currentTier.color} style={{ marginRight: 8 }} />
              <Text style={[styles.kycTitle, { color: theme.textPrimary, fontFamily: theme.fontFamily }]}>
                {currentTier.label}
              </Text>
            </View>
            <TouchableOpacity onPress={() => router.push('/kyc')} style={[styles.upgradeBtn, { backgroundColor: theme.primary }]}>
              <Text style={styles.upgradeBtnText}>UPGRADE</Text>
            </TouchableOpacity>
          </View>
          <Text style={[styles.kycLimitText, { color: theme.textSecondary, fontFamily: theme.fontFamily }]}>
            Limite journalière de transfert: <Text style={{ color: theme.textPrimary, fontWeight: '700' }}>{currentTier.limit}</Text>
          </Text>
        </Animated.View>

        {/* Menu Options */}
        <Animated.View entering={FadeInUp.duration(500).delay(300)} style={styles.menuSection}>
          <Text style={[styles.sectionTitle, { color: theme.textSecondary, fontFamily: theme.fontFamily }]}>PARAMÈTRES</Text>

          <View style={[styles.menuList, { backgroundColor: theme.surface, borderColor: theme.border }]}>
            {/* Dark Mode Toggle */}
            <View style={[styles.menuRow, { borderBottomWidth: 1, borderBottomColor: theme.border }]}>
              <View style={styles.menuRowLeft}>
                <Ionicons name="moon-outline" size={20} color={theme.primary} style={{ marginRight: 15 }} />
                <Text style={[styles.menuLabel, { color: theme.textPrimary, fontFamily: theme.fontFamily }]}>Mode Sombre</Text>
              </View>
              <Switch
                value={isDark}
                onValueChange={toggleTheme}
                trackColor={{ false: '#718096', true: theme.primary }}
                thumbColor={isDark ? '#000000' : '#FFFFFF'}
              />
            </View>

            {/* Manage Wallet */}
            <TouchableOpacity 
              style={[styles.menuRow, { borderBottomWidth: 1, borderBottomColor: theme.border }]}
              onPress={() => router.push('/cards')}
            >
              <View style={styles.menuRowLeft}>
                <Ionicons name="card-outline" size={20} color={theme.primary} style={{ marginRight: 15 }} />
                <Text style={[styles.menuLabel, { color: theme.textPrimary, fontFamily: theme.fontFamily }]}>Portefeuille & Cartes</Text>
              </View>
              <Feather name="chevron-right" size={18} color={theme.inactiveToken} />
            </TouchableOpacity>

            {/* Factures & Reçus */}
            <TouchableOpacity 
              style={[styles.menuRow, { borderBottomWidth: 1, borderBottomColor: theme.border }]}
              onPress={() => router.push('/factures')}
            >
              <View style={styles.menuRowLeft}>
                <Ionicons name="receipt-outline" size={20} color={theme.primary} style={{ marginRight: 15 }} />
                <Text style={[styles.menuLabel, { color: theme.textPrimary, fontFamily: theme.fontFamily }]}>Factures & Reçus</Text>
              </View>
              <Feather name="chevron-right" size={18} color={theme.inactiveToken} />
            </TouchableOpacity>

            {/* KYC Settings */}
            <TouchableOpacity 
              style={[styles.menuRow, { borderBottomWidth: 1, borderBottomColor: theme.border }]}
              onPress={() => router.push('/kyc')}
            >
              <View style={styles.menuRowLeft}>
                <Ionicons name="finger-print-outline" size={20} color={theme.primary} style={{ marginRight: 15 }} />
                <Text style={[styles.menuLabel, { color: theme.textPrimary, fontFamily: theme.fontFamily }]}>Statut KYC / Limites</Text>
              </View>
              <Feather name="chevron-right" size={18} color={theme.inactiveToken} />
            </TouchableOpacity>

            {/* App Settings Screen */}
            <TouchableOpacity 
              style={styles.menuRow}
              onPress={() => router.push('/settings')}
            >
              <View style={styles.menuRowLeft}>
                <Ionicons name="settings-outline" size={20} color={theme.primary} style={{ marginRight: 15 }} />
                <Text style={[styles.menuLabel, { color: theme.textPrimary, fontFamily: theme.fontFamily }]}>Paramètres Système</Text>
              </View>
              <Feather name="chevron-right" size={18} color={theme.inactiveToken} />
            </TouchableOpacity>
          </View>
        </Animated.View>

        {/* Logout Button */}
        <Animated.View entering={FadeInUp.duration(500).delay(400)} style={{ marginTop: 30 }}>
          <TouchableOpacity style={[styles.logoutBtn, { borderColor: '#EF4444' }]} onPress={handleLogout}>
            <Ionicons name="log-out-outline" size={20} color="#EF4444" style={{ marginRight: 8 }} />
            <Text style={[styles.logoutBtnText, { fontFamily: theme.fontFamily }]}>Déconnexion</Text>
          </TouchableOpacity>
        </Animated.View>

      </ScrollView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1 },
  header: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingHorizontal: 20,
    paddingTop: Platform.OS === 'ios' ? 10 : 30,
    paddingBottom: 15,
    borderBottomWidth: 1,
  },
  headerTitle: { fontSize: 16, textTransform: 'uppercase', letterSpacing: 2 },
  iconBtn: { width: 44, height: 44, justifyContent: 'center', alignItems: 'center', borderRadius: 22 },
  scrollContent: { paddingHorizontal: 20, paddingBottom: 110 },

  profileSection: {
    alignItems: 'center',
    marginVertical: 25,
  },
  avatarContainer: {
    width: 90,
    height: 90,
    borderRadius: 45,
    borderWidth: 2.5,
    justifyContent: 'center',
    alignItems: 'center',
    position: 'relative',
    marginBottom: 15,
  },
  avatarText: {
    fontSize: 36,
    fontWeight: '700',
  },
  verifiedBadge: {
    position: 'absolute',
    bottom: 2,
    right: 2,
    width: 22,
    height: 22,
    borderRadius: 11,
    justifyContent: 'center',
    alignItems: 'center',
    borderWidth: 2,
    borderColor: '#000',
  },
  usernameText: {
    fontSize: 20,
    fontWeight: '700',
    marginBottom: 4,
  },
  phoneText: {
    fontSize: 12,
    textTransform: 'uppercase',
    letterSpacing: 1,
  },

  kycCard: {
    borderRadius: 20,
    padding: 20,
    borderWidth: 1,
    marginBottom: 30,
  },
  kycHeader: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 12,
  },
  kycTitle: {
    fontSize: 14,
    fontWeight: '700',
    textTransform: 'uppercase',
    letterSpacing: 0.5,
  },
  upgradeBtn: {
    paddingHorizontal: 12,
    paddingVertical: 6,
    borderRadius: 12,
  },
  upgradeBtnText: {
    color: '#000',
    fontSize: 9,
    fontWeight: '800',
    letterSpacing: 0.5,
  },
  kycLimitText: {
    fontSize: 12,
  },

  menuSection: {
    marginBottom: 10,
  },
  sectionTitle: {
    fontSize: 11,
    letterSpacing: 1.5,
    marginBottom: 10,
    fontWeight: '700',
    paddingLeft: 5,
  },
