import React, { useState } from 'react';
import { View, Text, StyleSheet, Platform, SafeAreaView, TouchableOpacity, ScrollView, Dimensions, Modal, ActivityIndicator } from 'react-native';
import { Feather } from '@expo/vector-icons';
import { useAppTheme } from '@/context/ThemeContext';
import { useAuth } from '@/context/AuthContext';
import { fetchAPI } from '@/config/api';
import { router } from 'expo-router';
import Animated, { FadeInDown, FadeInUp } from 'react-native-reanimated';
import { LinearGradient } from 'expo-linear-gradient';

const { width } = Dimensions.get('window');

export default function CardsScreen() {
  const { colors: theme, isDark } = useAppTheme();
  const { username } = useAuth();

  const [showCardDetails, setShowCardDetails] = useState(false);
  const [addCardModalVisible, setAddCardModalVisible] = useState(false);
  const [newCardType, setNewCardType] = useState<'virtual' | 'physical'>('virtual');

  // Dynamic state for cards list
  const [cards, setCards] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  React.useEffect(() => {
    const loadCards = async () => {
      try {
        const res = await fetchAPI('/cards/');
        if (res && res.length > 0) {
          const mappedCards = res.map((c: any) => ({
            id: c.id,
            type: c.card_type === 'VIRTUAL' ? 'Visa Virtuelle' : 'Visa Physique',
            number: `•••• •••• •••• ${c.card_number.slice(-4)}`,
            fullNumber: c.card_number,
            expiry: c.expiration_date,
            cvv: c.cvv,
            balance: c.daily_limit,
            isFrozen: c.status === 'BLOCKED',
          }));
          setCards(mappedCards);
        } else {
          // Fallback mock card if no cards found for demonstration
          setCards([{
            id: 'virtual-1',
            type: 'Visa Virtuelle',
            number: '•••• •••• •••• 4242',
            fullNumber: '4242 4242 4242 4242',
            expiry: '12/28',
            cvv: '123',
            balance: 150000,
            isFrozen: false,
          }]);
        }
      } catch (error) {
        console.error(error);
      } finally {
        setLoading(false);
      }
    };
    loadCards();
  }, []);
  const [activeCardIndex, setActiveCardIndex] = useState(0);

  const currentCard = cards[activeCardIndex] || cards[0];

  const handleScroll = (event: any) => {
    const slideSize = event.nativeEvent.layoutMeasurement.width;
    const offset = event.nativeEvent.contentOffset.x;
    const index = Math.round(offset / (width - 30));
    if (index >= 0 && index < cards.length) {
      setActiveCardIndex(index);
    }
  };

  const handleAddCardSubmit = async () => {
    try {
      const newCardRes = await fetchAPI('/cards/virtual', { method: 'POST' });
      const newCard = {
        id: newCardRes.id,
        type: newCardRes.card_type === 'VIRTUAL' ? 'Visa Virtuelle' : 'Visa Physique',
        number: `•••• •••• •••• ${newCardRes.card_number.slice(-4)}`,
        fullNumber: newCardRes.card_number,
        expiry: newCardRes.expiration_date,
        cvv: newCardRes.cvv,
        balance: newCardRes.daily_limit,
        isFrozen: newCardRes.status === 'BLOCKED',
      };
      // If we only had the mock card, replace it. Otherwise append.
      if (cards.length === 1 && cards[0].id === 'virtual-1') {
        setCards([newCard]);
      } else {
        setCards([...cards, newCard]);
      }
      setAddCardModalVisible(false);
    } catch (error) {
      console.error(error);
    }
  };

  const toggleFreezeActiveCard = async () => {
    if (!currentCard) return;
    try {
      if (!currentCard.isFrozen && currentCard.id !== 'virtual-1') {
        await fetchAPI(`/cards/${currentCard.id}/block`, { method: 'POST' });
      }
      const updatedCards = [...cards];
      updatedCards[activeCardIndex].isFrozen = !updatedCards[activeCardIndex].isFrozen;
      setCards(updatedCards);
    } catch (error) {
      console.error(error);
    }
  };

  const CardAction = ({ icon, label, onPress, danger }: any) => (
    <TouchableOpacity 
      style={[styles.cardActionBtn, { backgroundColor: isDark ? 'rgba(255,255,255,0.05)' : theme.surface, borderColor: theme.border }]} 
      onPress={onPress}
    >
      <Feather name={icon} size={20} color={danger ? theme.danger : theme.primary} style={{ marginBottom: 8 }} />
      <Text style={[styles.cardActionLabel, { color: danger ? theme.danger : theme.textPrimary, fontFamily: theme.fontFamily }]}>{label}</Text>
    </TouchableOpacity>
  );

  if (loading || !currentCard) {
    return (
      <View style={[styles.container, { backgroundColor: isDark ? '#000000' : '#FFFFFF', justifyContent: 'center', alignItems: 'center' }]}>
        <ActivityIndicator size="large" color="#D4AF37" />
      </View>
    );
  }

  return (
    <View style={styles.container}>
      <LinearGradient
        colors={isDark ? ['#1a1500', '#000000', '#0a0a0a'] : ['#FFFDF5', '#FFFFFF', '#F8F9FA']}
        style={StyleSheet.absoluteFillObject}
      />
      <View style={[StyleSheet.absoluteFillObject, { backgroundColor: isDark ? 'rgba(0,0,0,0.4)' : 'transparent' }]} />

      <SafeAreaView style={{ flex: 1 }}>
        {/* Header */}
        <Animated.View entering={FadeInDown.duration(500)} style={styles.header}>
          <TouchableOpacity style={[styles.iconBtn, { backgroundColor: isDark ? 'rgba(255,255,255,0.1)' : theme.surface, borderColor: theme.border }]} onPress={() => router.back()}>
            <Feather name="arrow-left" size={20} color={theme.textPrimary} />
          </TouchableOpacity>
          <Text style={[styles.headerTitle, { color: theme.textPrimary, fontFamily: theme.fontFamily }]}>Cartes Bancaires</Text>
          <View style={{ width: 44 }} />
        </Animated.View>

        {/* Carousel of Cards */}
        <ScrollView 
          horizontal 
          showsHorizontalScrollIndicator={false}
          onScroll={handleScroll}
          scrollEventThrottle={16}
          snapToInterval={width - 30}
          snapToAlignment="start"
          decelerationRate="fast"
          contentContainerStyle={styles.cardCarousel}
        >
          {cards.map((card) => {
            const currentCardNumber = showCardDetails ? card.fullNumber : card.number;
            const currentCvv = showCardDetails ? card.cvv : '•••';

            return (
              <View key={card.id} style={{ width: width - 40, marginRight: 10 }}>
                <View style={styles.cardWrapper}>
                  <View style={[styles.glowShadow, { shadowColor: card.isFrozen ? theme.danger : '#D4AF37' }]} />

                  {/* Premium Gold Card with transparent designer stripes */}
                  <LinearGradient 
                    colors={card.isFrozen ? ['#4A4A4A', '#2E2E2E'] : ['#F4C430', '#C59B27', '#9A7B1C']} 
                    start={{ x: 0, y: 0 }}
                    end={{ x: 1, y: 1 }}
                    style={[styles.creditCard, { borderColor: card.isFrozen ? theme.danger : '#D4AF37', borderWidth: 1 }]}
                  >
                    {/* Transparent designer stripes */}
                    <View style={styles.stripe1} />
                    <View style={styles.stripe2} />
                    <View style={styles.stripe3} />

                    <View style={styles.cardHeader}>
                      <Feather name="cpu" size={32} color="#000" style={{ opacity: 0.9 }} />
                      <Text style={[styles.cardBrand, { color: '#000', fontFamily: theme.fontFamily }]}>XAALISI</Text>
                    </View>

                    <View style={styles.cardNumberBox}>
                      <Text style={[styles.cardNumber, { color: '#000', fontFamily: theme.fontFamily, fontWeight: '700' }]}>{currentCardNumber}</Text>
                    </View>

                    <View style={styles.cardFooter}>
                      <View>
                        <Text style={[styles.cardLabel, { color: 'rgba(0,0,0,0.6)', fontFamily: theme.fontFamily }]}>Titulaire</Text>
                        <Text style={[styles.cardValue, { color: '#000', fontFamily: theme.fontFamily, fontWeight: '600' }]}>{username ? username.toUpperCase() : 'UTILISATEUR'}</Text>
                      </View>
                      <View style={{ alignItems: 'center' }}>
                        <Text style={[styles.cardLabel, { color: 'rgba(0,0,0,0.6)', fontFamily: theme.fontFamily }]}>Expire</Text>
                        <Text style={[styles.cardValue, { color: '#000', fontFamily: theme.fontFamily, fontWeight: '600' }]}>{card.expiry}</Text>
                      </View>
                      <View style={{ alignItems: 'flex-end' }}>
                        <Text style={[styles.cardLabel, { color: 'rgba(0,0,0,0.6)', fontFamily: theme.fontFamily }]}>CVV</Text>
                        <Text style={[styles.cardValue, { color: '#000', fontFamily: theme.fontFamily, fontWeight: '600' }]}>{currentCvv}</Text>
                      </View>
                    </View>

                    {card.isFrozen && (
                      <View style={[StyleSheet.absoluteFillObject, styles.frozenOverlay]}>
                        <Feather name="lock" size={40} color="#FFF" />
                        <Text style={[styles.frozenText, { fontFamily: theme.fontFamily }]}>CARTE BLOQUÉE</Text>
                      </View>
                    )}
                  </LinearGradient>
                </View>
              </View>
            );
          })}

          {/* Ajouter une carte placeholder */}
          <TouchableOpacity 
            style={[styles.addCardPlaceholder, { width: width - 40, borderColor: isDark ? '#444' : '#D0D0D0' }]} 
            onPress={() => setAddCardModalVisible(true)}
            activeOpacity={0.8}
          >
            <View style={[styles.addCardIconBox, { borderColor: theme.primary }]}>
              <Feather name="plus" size={32} color={theme.primary} />
            </View>
            <Text style={[styles.addCardText, { color: theme.textPrimary, fontFamily: theme.fontFamily }]}>AJOUTER UNE CARTE</Text>
          </TouchableOpacity>
        </ScrollView>

        <ScrollView contentContainerStyle={styles.scrollContent} showsVerticalScrollIndicator={false}>

          <Animated.View entering={FadeInUp.duration(600).delay(200)}>

            <View style={styles.balanceBox}>
              <Text style={[styles.balanceLabel, { color: theme.textSecondary, fontFamily: theme.fontFamily }]}>Solde lié à la carte ({currentCard.type})</Text>
              <Text style={[styles.balanceValue, { color: theme.textPrimary, fontFamily: theme.fontFamily }]}>{currentCard.balance.toLocaleString()} FCFA</Text>
            </View>

            {/* Quick Actions for Cards */}
            <View style={styles.actionGrid}>
              <CardAction 
                icon={showCardDetails ? "eye-off" : "eye"} 
                label={showCardDetails ? "Masquer" : "Afficher"} 
                onPress={() => setShowCardDetails(!showCardDetails)} 
              />
              <CardAction 
                icon={currentCard.isFrozen ? "unlock" : "lock"} 
                label={currentCard.isFrozen ? "Débloquer" : "Bloquer"} 
                onPress={toggleFreezeActiveCard} 
                danger={!currentCard.isFrozen}
              />
              <CardAction 
                icon="settings" 
                label="Limites" 
                onPress={() => {}} 
              />
            </View>

            <View style={styles.infoSection}>
              <Text style={[styles.infoTitle, { color: theme.textPrimary, fontFamily: theme.fontFamily }]}>Détails de la carte</Text>
              <View style={[styles.infoCard, { backgroundColor: isDark ? 'rgba(255,255,255,0.03)' : theme.surface, borderColor: theme.border }]}>
                <View style={styles.infoRow}>
                  <Text style={[styles.infoLabel, { color: theme.textSecondary, fontFamily: theme.fontFamily }]}>Type de carte</Text>
                  <Text style={[styles.infoValue, { color: theme.textPrimary, fontFamily: theme.fontFamily }]}>{currentCard.type}</Text>
                </View>
                <View style={styles.infoRow}>
                  <Text style={[styles.infoLabel, { color: theme.textSecondary, fontFamily: theme.fontFamily }]}>Plafond Mensuel</Text>
                  <Text style={[styles.infoValue, { color: theme.textPrimary, fontFamily: theme.fontFamily }]}>500,000 FCFA</Text>
                </View>
                <View style={[styles.infoRow, { borderBottomWidth: 0 }]}>
                  <Text style={[styles.infoLabel, { color: theme.textSecondary, fontFamily: theme.fontFamily }]}>Paiement sans contact</Text>
                  <Text style={[styles.infoValue, { color: theme.success, fontFamily: theme.fontFamily }]}>Activé</Text>
                </View>
              </View>
            </View>

          </Animated.View>
        </ScrollView>
      </SafeAreaView>

      {/* Add Card Modal */}
      <Modal
        visible={addCardModalVisible}
        animationType="slide"
        transparent
        onRequestClose={() => setAddCardModalVisible(false)}
      >
        <View style={styles.modalOverlay}>
          <Animated.View entering={FadeInUp.duration(400)} style={[styles.modalContent, { backgroundColor: theme.background }]}>
            <View style={styles.modalHeader}>
              <Text style={[styles.modalTitle, { color: theme.textPrimary, fontFamily: theme.fontFamily }]}>Ajouter une carte</Text>
              <TouchableOpacity style={[styles.closeBtn, { backgroundColor: isDark ? 'rgba(255,255,255,0.1)' : theme.surface }]} onPress={() => setAddCardModalVisible(false)}>
                <Feather name="x" size={20} color={theme.textPrimary} />
              </TouchableOpacity>
            </View>

            <View style={styles.formInputGroup}>
              <Text style={[styles.formLabel, { color: theme.textSecondary, fontFamily: theme.fontFamily, marginBottom: 12 }]}>TYPE DE CARTE</Text>
              <View style={{ flexDirection: 'row', gap: 10 }}>
                <TouchableOpacity 
                  style={[styles.modalTabBtn, newCardType === 'virtual' && { backgroundColor: theme.primary }]}
                  onPress={() => setNewCardType('virtual')}
                >
                  <Text style={{ color: newCardType === 'virtual' ? '#000' : theme.textSecondary, fontFamily: theme.fontFamily, fontWeight: '700' }}>Virtuelle</Text>
                </TouchableOpacity>
                <TouchableOpacity 
                  style={[styles.modalTabBtn, newCardType === 'physical' && { backgroundColor: theme.primary }]}
                  onPress={() => setNewCardType('physical')}
                >
                  <Text style={{ color: newCardType === 'physical' ? '#000' : theme.textSecondary, fontFamily: theme.fontFamily, fontWeight: '700' }}>Physique</Text>
                </TouchableOpacity>
              </View>
            </View>

            <TouchableOpacity
              style={[styles.submitBtn, { backgroundColor: theme.primary }]}
              onPress={handleAddCardSubmit}
            >
              <Text style={{ color: '#000', fontSize: 14, fontWeight: '700', fontFamily: theme.fontFamily }}>CRÉER LA CARTE</Text>
            </TouchableOpacity>
          </Animated.View>
        </View>
      </Modal>
    </View>
  );
}

