import React, { useState } from 'react';
import { View, Text, StyleSheet, SafeAreaView, TouchableOpacity, TextInput, Alert, ScrollView } from 'react-native';
import { Feather } from '@expo/vector-icons';
import { useAppTheme } from '@/context/ThemeContext';
import { fetchAPI } from '@/config/api';
import { router } from 'expo-router';
import Animated, { FadeInDown, FadeInUp } from 'react-native-reanimated';
import { LinearGradient } from 'expo-linear-gradient';

export default function ChequesScreen() {
  const { colors: theme, isDark } = useAppTheme();
  
  const [activeTab, setActiveTab] = useState<'request' | 'opposition'>('request');
  
  // Request State
  const [pagesCount, setPagesCount] = useState<number>(25);
  const [requestLoading, setRequestLoading] = useState(false);
  
  // Opposition State
  const [chequeNumber, setChequeNumber] = useState('');
  const [amount, setAmount] = useState('');
  const [reason, setReason] = useState('');
  const [oppositionLoading, setOppositionLoading] = useState(false);

  const handleRequest = async () => {
    setRequestLoading(true);
    try {
      // Mocking account ID with user's primary for now
      await fetchAPI('/cheques/request', {
        method: 'POST',
        body: JSON.stringify({ account_id: 'default_account', pages_count: pagesCount })
      });
      Alert.alert('Succès', 'Votre demande de chéquier a été envoyée.');
    } catch (error) {
      Alert.alert('Erreur', 'Impossible de demander le chéquier.');
    } finally {
      setRequestLoading(false);
    }
  };

  const handleOpposition = async () => {
    if (!chequeNumber || !reason) {
      Alert.alert('Erreur', 'Veuillez remplir le numéro de chèque et le motif.');
      return;
    }
    setOppositionLoading(true);
    try {
      await fetchAPI('/cheques/opposition', {
        method: 'POST',
        body: JSON.stringify({ 
          cheque_number: chequeNumber, 
          amount: amount ? parseFloat(amount) : null,
          reason 
        })
      });
      Alert.alert('Succès', 'Opposition enregistrée.');
      setChequeNumber('');
      setAmount('');
      setReason('');
    } catch (error) {
      Alert.alert('Erreur', "Impossible d'enregistrer l'opposition.");
    } finally {
      setOppositionLoading(false);
    }
  };

  return (
    <View style={styles.container}>
      <LinearGradient
        colors={isDark ? ['#1a1500', '#000000', '#0a0a0a'] : ['#FFFDF5', '#FFFFFF', '#F8F9FA']}
        style={StyleSheet.absoluteFillObject}
      />
      <SafeAreaView style={{ flex: 1 }}>
        <Animated.View entering={FadeInDown.duration(500)} style={styles.header}>
          <TouchableOpacity style={[styles.iconBtn, { backgroundColor: isDark ? 'rgba(255,255,255,0.1)' : theme.surface, borderColor: theme.border }]} onPress={() => router.back()}>
            <Feather name="arrow-left" size={20} color={theme.textPrimary} />
          </TouchableOpacity>
          <Text style={[styles.headerTitle, { color: theme.textPrimary, fontFamily: theme.fontFamily }]}>Chèques</Text>
          <View style={{ width: 44 }} />
        </Animated.View>

        <View style={styles.tabContainer}>
          <TouchableOpacity 
            style={[styles.tab, activeTab === 'request' && styles.activeTab, activeTab === 'request' && { borderBottomColor: theme.primary }]} 
            onPress={() => setActiveTab('request')}
          >
            <Text style={[styles.tabText, { color: activeTab === 'request' ? theme.primary : theme.textSecondary, fontFamily: theme.fontFamily }]}>Demander un Chéquier</Text>
          </TouchableOpacity>
          <TouchableOpacity 
            style={[styles.tab, activeTab === 'opposition' && styles.activeTab, activeTab === 'opposition' && { borderBottomColor: theme.primary }]} 
            onPress={() => setActiveTab('opposition')}
          >
            <Text style={[styles.tabText, { color: activeTab === 'opposition' ? theme.primary : theme.textSecondary, fontFamily: theme.fontFamily }]}>Faire Opposition</Text>
          </TouchableOpacity>
        </View>

        <ScrollView contentContainerStyle={styles.content}>
          {activeTab === 'request' ? (
            <Animated.View entering={FadeInUp.duration(400)}>
              <Text style={[styles.label, { color: theme.textPrimary, fontFamily: theme.fontFamily }]}>Format du chéquier (Pages)</Text>
              <View style={styles.formatSelector}>
                {[25, 50, 100].map(num => (
                  <TouchableOpacity 
                    key={num} 
                    style={[styles.formatBtn, pagesCount === num ? { backgroundColor: theme.primary } : { backgroundColor: isDark ? '#222' : '#EEE' }]}
                    onPress={() => setPagesCount(num)}
                  >
                    <Text style={[styles.formatText, pagesCount === num ? { color: '#000' } : { color: theme.textSecondary }, { fontFamily: theme.fontFamily }]}>{num}</Text>
                  </TouchableOpacity>
                ))}
              </View>

              <TouchableOpacity style={[styles.submitBtn, { backgroundColor: theme.primary }]} onPress={handleRequest} disabled={requestLoading}>
                <Text style={[styles.submitText, { fontFamily: theme.fontFamily }]}>{requestLoading ? 'Envoi...' : 'Commander le chéquier'}</Text>
              </TouchableOpacity>
            </Animated.View>
          ) : (
            <Animated.View entering={FadeInUp.duration(400)}>
              <Text style={[styles.label, { color: theme.textPrimary, fontFamily: theme.fontFamily }]}>Numéro de chèque *</Text>
              <TextInput 
                style={[styles.input, { backgroundColor: theme.surface, color: theme.textPrimary, borderColor: theme.border, fontFamily: theme.fontFamily }]} 
                placeholder="Ex: 0001234567"
                placeholderTextColor={theme.textSecondary}
                value={chequeNumber}
                onChangeText={setChequeNumber}
              />
              
              <Text style={[styles.label, { color: theme.textPrimary, fontFamily: theme.fontFamily }]}>Montant (Optionnel)</Text>
              <TextInput 
                style={[styles.input, { backgroundColor: theme.surface, color: theme.textPrimary, borderColor: theme.border, fontFamily: theme.fontFamily }]} 
                placeholder="Ex: 50000"
                placeholderTextColor={theme.textSecondary}
                keyboardType="numeric"
                value={amount}
                onChangeText={setAmount}
              />

              <Text style={[styles.label, { color: theme.textPrimary, fontFamily: theme.fontFamily }]}>Motif de l'opposition *</Text>
              <TextInput 
                style={[styles.input, { backgroundColor: theme.surface, color: theme.textPrimary, borderColor: theme.border, fontFamily: theme.fontFamily, height: 100, textAlignVertical: 'top' }]} 
                placeholder="Ex: Perte, vol..."
                placeholderTextColor={theme.textSecondary}
                multiline
                value={reason}
                onChangeText={setReason}
              />

              <TouchableOpacity style={[styles.submitBtn, { backgroundColor: theme.danger }]} onPress={handleOpposition} disabled={oppositionLoading}>
                <Text style={[styles.submitText, { fontFamily: theme.fontFamily, color: '#FFF' }]}>{oppositionLoading ? 'Enregistrement...' : "Confirmer l'opposition"}</Text>
              </TouchableOpacity>
            </Animated.View>
          )}
        </ScrollView>
      </SafeAreaView>
    </View>
  );
}

