          <View style={[styles.avatarLg, { borderColor: colors.primary }]}>
            <Text style={[styles.avatarTextLg, { color: colors.primary, fontFamily: colors.fontFamily }]}>{username?.charAt(0).toUpperCase() || 'U'}</Text>
          </View>
          <View style={styles.profileInfo}>
            <Text style={[styles.profileName, { color: colors.textPrimary, fontFamily: colors.fontFamily }]}>{username || 'Utilisateur'}</Text>
            <Text style={[styles.profileId, { color: colors.textSecondary, fontFamily: colors.fontFamily }]}>ID XAALISI: {username?.toUpperCase()}-XL</Text>
            <View style={[styles.kycBadge, { backgroundColor: colors.primary + '20' }]}>
              <Feather name="shield" size={12} color={colors.primary} style={{ marginRight: 4 }} />
              <Text style={[styles.kycText, { color: colors.primary, fontFamily: colors.fontFamily }]}>KYC Niveau 2</Text>
            </View>
          </View>
        </Animated.View>

        <MenuSection 
          title="SÉCURITÉ" 
          delay={100}
          items={[
            { icon: 'lock', label: 'Modifier le code PIN', action: () => Alert.alert('Sécurité', 'Le portail de modification de PIN s\'ouvrira ici.') },
            { icon: 'shield', label: 'Limites de transaction', action: () => Alert.alert('Sécurité', 'Limites: 500,000 FCFA par jour.') }
          ]} 
        />

        <MenuSection 
          title="PRÉFÉRENCES" 
          delay={200}
          items={[
            { icon: 'globe', label: 'Langue', action: toggleLanguage, value: lang },
            { icon: 'bell', label: 'Notifications', action: () => router.push('/notifications') },
            { icon: 'moon', label: 'Mode Sombre', action: toggleTheme, value: isDark ? 'Activé' : 'Désactivé' }
