        />

        <MenuSection 
          title="XAALISI SERVICES" 
          delay={100}
          items={[
            { icon: 'send', label: 'Transfert d\'argent', action: () => router.push('/(tabs)/transfers') },
            { icon: 'shopping-cart', label: 'Paiement Marchand', action: () => router.push('/merchant') },
            { icon: 'file-text', label: 'Paiement Factures', action: () => router.push('/factures') },
            { icon: 'users', label: 'Tontines (Darét)', action: () => router.push('/tontines') },
            { icon: 'globe', label: 'Transfert International', action: () => router.push('/(tabs)/transfers'), isNew: true },
