        />

        <MenuSection 
          title="AIDE & SUPPORT" 
          delay={300}
          items={[
            { icon: 'help-circle', label: 'Centre d\'aide', action: () => router.push('/help') },
            { icon: 'message-circle', label: 'Contacter le support', action: () => router.push('/support') },
