            { icon: 'log-out', label: 'Se déconnecter', action: handleLogout, danger: true }
          ]} 
        />

        <Text style={[styles.versionText, { color: colors.inactiveToken, fontFamily: colors.fontFamily }]}>XAALISI v1.0.0 (Build 2026)</Text>
      </ScrollView>
    </SafeAreaView>
  );
}

